package org.sleepwell.app;
import android.content.Context;import java.io.*;import java.util.*;import java.util.function.BooleanSupplier;
/** Original local PCM generator. Called only by the explicit-play decoder path. */
final class BinauralTones {
 static final String NAME="Binaural tones",PREFIX="binaural:v1:";static final int RATE=48000,SECONDS=4;static final double PEAK=.08;
 static void validate(int carrier,int beat){if(carrier<100||carrier>400||beat<1||beat>20)throw new IllegalArgumentException("Choose a carrier of 100–400 Hz and a difference of 1–20 Hz.");}
 static String source(int carrier,int beat){validate(carrier,beat);return PREFIX+carrier+":"+beat;}
 static int[] parse(String source){if(source==null||!source.startsWith(PREFIX))throw new IllegalArgumentException("Unknown stereo tone source.");String[] values=source.substring(PREFIX.length()).split(":",-1);if(values.length!=2)throw new IllegalArgumentException("Invalid stereo tone source.");int carrier=Integer.parseInt(values[0]),beat=Integer.parseInt(values[1]);validate(carrier,beat);if(!source.equals(source(carrier,beat)))throw new IllegalArgumentException("Invalid stereo tone source.");return new int[]{carrier,beat};}
 static File prepare(Context context,String source,BooleanSupplier active)throws IOException {int[] values=parse(source);File cache=context.getCacheDir().getCanonicalFile(),root=new File(cache,"binaural-tones").getCanonicalFile();if(!cache.equals(root.getParentFile())||!root.isDirectory()&&!root.mkdirs())throw new IOException("Stereo tone storage unavailable.");File target=new File(root,"stereo-v1-"+values[0]+"-"+values[1]+".wav");long length=44L+RATE*SECONDS*4L;check(active);if(target.isFile()&&target.length()==length&&target.getCanonicalFile().equals(target.getAbsoluteFile()))return target;File temporary=new File(root,"pending-"+UUID.randomUUID()+".wav");try{try(FileOutputStream output=new FileOutputStream(temporary)){byte[] header=new byte[44];ascii(header,0,"RIFF");le(header,4,(int)length-8,4);ascii(header,8,"WAVEfmt ");le(header,16,16,4);le(header,20,1,2);le(header,22,2,2);le(header,24,RATE,4);le(header,28,RATE*4,4);le(header,32,4,2);le(header,34,16,2);ascii(header,36,"data");le(header,40,RATE*SECONDS*4,4);output.write(header);byte[] block=new byte[4096];int used=0;for(int sample=0;sample<RATE*SECONDS;sample++){if((sample&1023)==0)check(active);short left=(short)Math.round(32767*PEAK*Math.sin(2*Math.PI*values[0]*sample/RATE)),right=(short)Math.round(32767*PEAK*Math.sin(2*Math.PI*(values[0]+values[1])*sample/RATE));block[used++]=(byte)left;block[used++]=(byte)(left>>8);block[used++]=(byte)right;block[used++]=(byte)(right>>8);if(used==block.length){output.write(block);used=0;}}if(used>0)output.write(block,0,used);output.getFD().sync();}check(active);if(target.exists()&&!target.delete())throw new IOException("Stereo tone cache could not be replaced.");if(!temporary.renameTo(target))throw new IOException("Stereo tone cache could not be saved.");prune(root,target);return target;}finally{if(temporary.exists())temporary.delete();}}
 private static void check(BooleanSupplier active)throws IOException{if(!active.getAsBoolean()||Thread.currentThread().isInterrupted())throw new IOException("Stereo tone generation cancelled.");}
 private static void ascii(byte[] output,int start,String text){for(int n=0;n<text.length();n++)output[start+n]=(byte)text.charAt(n);}
 private static void le(byte[] output,int start,int value,int count){for(int n=0;n<count;n++)output[start+n]=(byte)(value>>(8*n));}
 private static void prune(File root,File keep){File[] files=root.listFiles();if(files==null)return;List<File> generated=new ArrayList<>();for(File file:files)try{if(file.isFile()&&file.getCanonicalFile().equals(file.getAbsoluteFile())&&file.getName().matches("stereo-v1-[0-9]{3}-[0-9]{1,2}\\.wav"))generated.add(file);else if(file.isFile()&&file.getCanonicalFile().equals(file.getAbsoluteFile())&&file.getName().matches("pending-[0-9a-f-]{36}\\.wav")&&System.currentTimeMillis()-file.lastModified()>86400000L)file.delete();}catch(IOException ignored){}generated.sort(Comparator.comparingLong(File::lastModified));int remaining=generated.size();for(File file:generated){if(remaining<=6)break;if(!file.equals(keep)&&file.delete())remaining--;}}
 private BinauralTones(){}
}
